import{_ as t}from"./chunks/Audio.COine8Wh.js";import{_ as s}from"./chunks/Tags.BJ536pW3.js";import{c as r,o as n,j as a,G as i,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Tribal Trust Land Homeownership Act of 2025","description":"","frontmatter":{"legisId":"2026-05-04-tribal-trust-land-homeownership-act-of-2025","title":"Tribal Trust Land Homeownership Act of 2025","displayTitle":"Tribal Trust Land Homeownership Act of 2025","lawNumber":"119-88","billNumber":"S. 723","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ88.xml","publishDate":"2026-05-04T00:00:00-05:00","industries":["housing","finance","government-operations"],"agencies":["Bureau of Indian Affairs"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Tribal Trust Land Homeownership Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Tribal Trust Land Homeownership Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025\\",\\"datePublished\\":\\"2026-05-04T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025.md","filePath":"congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-05-04-tribal-trust-land-homeownership-act-of-2025.md"},g=Object.assign(d,{setup(p){return(c,e)=>(n(),r("div",null,[e[0]||(e[0]=a("h1",{id:"tribal-trust-land-homeownership-act-of-2025",tabindex:"-1"},[l("Tribal Trust Land Homeownership Act of 2025 "),a("a",{class:"header-anchor",href:"#tribal-trust-land-homeownership-act-of-2025","aria-label":'Permalink to "Tribal Trust Land Homeownership Act of 2025"'},"​")],-1)),i(t),i(s,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Monday, May 4, 2026. Public Law 119-88, S. 723.</p><p><strong>Headline:</strong> The law sets firm federal deadlines for mortgages, rights-of-way, and title records involving Indian land.</p><p><strong>Why it matters:</strong> Faster, more transparent Bureau of Indian Affairs reviews could reduce administrative delays for homeownership, business financing, and land use on Indian land.</p><p><strong>What the law does:</strong></p><ul><li>Requires Bureau offices to check submissions for missing documents within 10 calendar days and notify lenders within 2 calendar days after finding omissions.</li><li>Sets 20-day decision deadlines for complete leasehold mortgage packages and 30-day deadlines for land mortgages and rights-of-way, with limited exceptions for certain approved tribal leasing arrangements.</li><li>Requires written decisions, explanations for disapprovals, prompt notices of missed deadlines, and responses to relevant status inquiries within 2 calendar days.</li><li>Generally requires title status reports within 10 calendar days after approval and requested first reports within 14 calendar days.</li><li>Gives federal lending agencies and Indian Tribes read-only access to relevant land-record portals.</li><li>Establishes annual performance reports, a federal digitization study, and a Realty Ombudsman to monitor compliance and resolve complaints.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Tribal members and other borrowers seeking homes or business financing on Indian land.</li><li>Indian Tribes, lenders, and parties submitting mortgage or right-of-way documents.</li><li>Bureau of Indian Affairs offices and federal lending agencies.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Applicants can expect clearer timelines and written explanations when mortgage or land-use requests are denied.</li><li>Borrowers and lenders receive faster notice of missing paperwork, delays, and application status.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="tribal-trust-land-homeownership-act-of-2025-1" tabindex="-1">Tribal Trust Land Homeownership Act of 2025 <a class="header-anchor" href="#tribal-trust-land-homeownership-act-of-2025-1" aria-label="Permalink to &quot;Tribal Trust Land Homeownership Act of 2025&quot;">​</a></h3><p>This law sets firm deadlines for the Bureau of Indian Affairs to review and decide on residential and business leasehold mortgages, land mortgages, and right-of-way documents involving Indian land. It also requires faster title reports, notices about delays, improved access to land records, annual performance reporting, and a Realty Ombudsman to oversee compliance and resolve complaints.</p><p><strong>Key takeaways:</strong></p><ul><li>Bureau offices must check mortgage and right-of-way packages for missing documents within 10 calendar days and notify lenders of missing items within 2 calendar days after finding them.</li><li>Bureau offices must approve or disapprove complete leasehold mortgage packages within 20 calendar days and complete land mortgage and right-of-way decisions within 30 calendar days.</li><li>Decisions must be in writing, and disapprovals must explain the reason, although the decision deadlines do not apply to certain tribal leasing arrangements already approved under federal law.</li><li>The Bureau must generally complete required title status reports within 10 calendar days after approval, while a requested first title status report must be completed within 14 calendar days.</li><li>If a deadline is missed, the Bureau must immediately notify the submitting party and lender, and it must answer relevant status inquiries within 2 calendar days.</li><li>Federal lending agencies and Indian Tribes receive read-only access to relevant Bureau land-record portals, while annual reports, a federal digitization study, and a new Realty Ombudsman provide oversight and support.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ88.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ88.xml</a></p>',15))]))}});export{h as __pageData,g as default};
